<script setup>
import { computed } from 'vue'
import { useSequence } from '../composables/useSequence'
const stages=[['Language + segmentation','Instructions became spatial adjustment maps.','Dependent on segmentation; required explicit instructions.'],['Dynamic grouping','Similar retouching adjustments formed virtual users.','Useful transfer results, but groups did not represent real users.'],['Memory slots','Historical edits were aggregated into learned slots.','Averaging and fixed styles limited preference diversity.'],['Similarity retrieval','Image embeddings were supervised by edit-vector distances.','Approximately 30% retrieval accuracy; one neighbour was unreliable.'],['Conditional density','Transformer conditioning + normalizing flow + candidate sampling.','Selected framework: continuous preferences and training-free adaptation.']]
const sequence=useSequence(stages.map(s=>s[0]));const current=computed(()=>stages[sequence.step.value])
</script>
<template><div class="stack"><div class="timeline"><button v-for="(s,i) in stages" :key="s[0]" :aria-pressed="sequence.step.value===i" @click.stop="sequence.seek(i)"><span>0{{i+1}}</span>{{s[0]}}</button></div><div class="split grow"><div class="col"><h2>{{current[0]}}</h2><p class="statement">{{current[1]}}</p><p class="note">{{current[2]}}</p></div><div class="evolution-shift"><div>Transfer / retrieve / average</div><span>↓</span><div class="blue">Predict p(z | O, H)</div><p class="small muted">The change was a reformulation of the task.</p></div></div><SequenceControls :sequence="sequence"/><p class="small muted">Five research stages are retained as historical context. Only the final framework is an active architecture component.</p></div></template>
